#include <vector>
#include <algorithm>

class Solution {
public:
    int maxSumRangeQuery(std::vector<int>& nums, std::vector<std::vector<int>>& requests) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        std::vector<int> diff(n + 1, 0);
        for (const auto& req : requests) {
            diff[req[0]]++;
            diff[req[1] + 1]--;
        }
        std::vector<int> freq(n, 0);
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            freq[i] = cur;
        }
        std::sort(freq.begin(), freq.end());
        std::sort(nums.begin(), nums.end());
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            ans = (ans + (long long)freq[i] * nums[i]) % MOD;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxSumRangeQuery(int[] nums, int[][] requests) {
        final int MOD = 1000000007;
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int[] req : requests) {
            diff[req[0]]++;
            diff[req[1] + 1]--;
        }
        int[] freq = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            freq[i] = cur;
        }
        Arrays.sort(freq);
        Arrays.sort(nums);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + (long) freq[i] * nums[i]) % MOD;
        }
        return (int) ans;
    }
}

var maxSumRangeQuery = function(nums, requests) {
    const MOD = 1000000007n;
    const n = nums.length;
    const diff = new Int32Array(n + 1);
    for (const [l, r] of requests) {
        diff[l]++;
        diff[r + 1]--;
    }
    const freq = new Int32Array(n);
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += diff[i];
        freq[i] = cur;
    }
    freq.sort();
    nums.sort((a, b) => a - b);
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        ans = (ans + BigInt(freq[i]) * BigInt(nums[i])) % MOD;
    }
